using System;using RichAudio.BatiResearch;
public static class DrivingActivationTests
{
 static int n;static void Yes(bool b,string why){n++;if(!b)throw new Exception(why);}
 public static int Main(string[] args){
  var g=new GameplayReadiness();Yes(!g.Observe(true,false,10),"open console blocks");Yes(!g.Observe(false,false,20),"closure needs baseline");Yes(!g.Observe(false,false,20),"frozen game clock blocks");Yes(g.Observe(false,false,21),"advancing clock admits");Yes(!g.Observe(false,true,22),"paused blocks");Yes(!g.Observe(false,false,23),"pause resets baseline");Yes(g.Observe(false,false,24),"advancing again");Yes(!g.Observe(null,false,25),"unknown console blocks");Yes(!g.Observe(false,false,null),"unknown clock blocks");Yes(!g.Observe(false,false,26),"baseline after missing clock");Yes(!g.Observe(false,false,25),"backward game clock blocks");
  var w=new FakeWorld();var c=TestBatiController.Ready(w);Yes(c.Start(0),"setup");c.Tick(20);Yes(w.Drives==0,"setup/settling cannot issue task");c.Observe(TestBatiController.R(c,20,0,0));Yes(c.State==Stage.Accelerating&&w.Drives==1,"long setup excluded");var d=c.Snapshot().Driving;Yes(d.FirstTaskRequestedAt==20&&d.InvocationReturned&&d.LastProgressAt==20,"task starts clock");for(int i=1;i<=25;i++)c.Observe(TestBatiController.R(c,20+i*.2,0,0));Yes(c.State==Stage.Accelerating,"five seconds inclusive allowed");c.Observe(TestBatiController.R(c,25.2,0,0));Yes(c.Snapshot().Reason=="stalled progression"&&w.Deleted.Count==2,"post-task stall cleanup");Yes(w.Drives==1&&w.Spawns==2,"no retry or extra entities");bool rejected=false;try{c.Start(26);}catch(InvalidOperationException){rejected=true;}Yes(rejected,"one shot retained");
  w=new FakeWorld();c=TestBatiController.Ready(w);c.Start(0);c.Observe(TestBatiController.R(c,20,0,0));for(int i=1;i<=25;i++)c.Observe(TestBatiController.R(c,20+i*.2,i*.3,1.5));Yes(c.State!=Stage.Cleaned&&c.Snapshot().Driving.LastProgressAt>20,"real progress refreshes");Yes(c.Snapshot().Driving.FirstMovementAt.HasValue,"movement timestamp");c.Tick(120.1);Yes(c.Snapshot().Reason=="run timeout","overall deadline remains from Start");
  foreach(var status in new[]{"UNKNOWN","NoTask","Interrupted","InProgress"}){w=new FakeWorld();c=TestBatiController.Ready(w);c.Start(0);var r=TestBatiController.R(c,0,0,0);r.TaskState=status;c.Observe(r);Yes(c.Snapshot().Driving.TaskState==status&&w.Drives==1,"generic status retained without invented task identity");c.Abort();}
  w=new FakeWorld{DriveFailure=true};c=TestBatiController.Ready(w);c.Start(0);c.Observe(TestBatiController.R(c,0,0,0));d=c.Snapshot().Driving;Yes(d.InvocationAttempted&&!d.InvocationReturned&&d.ExceptionType=="InvalidOperationException","invocation exception retained");Yes(c.State==Stage.Cleaned&&w.Deleted.Count==2&&w.Drives==1,"exception cleanup no fallback");
  Console.WriteLine("PASS: "+n+" original driving activation assertions; offline only.");return 0;
 }
}
